-- HANA-SOURCE: cl/bcs/tesoreria/sql/GestionDeDepositos_UpdateDeposito_EntidadDeposito.sql
-- H2 rewrite: TO_DATE(..) || ' ' || TO_VARCHAR(CURRENT_UTCTIMESTAMP,'HH24:MI:SS.FF7') = date + fixed clock time + 7 zero decimals. Params: TipoEjecucion, IdConcepto, Descripcion, TipoEjecucion, IdUsuario, TipoEjecucion, FechaMovimiento, Id, Entidad.
UPDATE "BSCL.Tesoreria.BD::TES.Deposito" AS DEP SET "IdEstado" = :TipoEjecucion, "IdConcepto" = :IdConcepto, "Descripcion" = :Descripcion, "IdUsuarioLiquidador" = CASE WHEN :TipoEjecucion = 'LIQ' THEN :IdUsuario ELSE DEP."IdUsuarioLiquidador" END, "FechaHoraLiquidacion" = CASE WHEN :TipoEjecucion = 'LIQ' THEN CAST(CAST(PARSEDATETIME(:FechaMovimiento, 'yyyy-MM-dd') AS DATE) || ' ' || FORMATDATETIME(HANA_UTCNOW(), 'HH:mm:ss') || '.0000000' AS TIMESTAMP) ELSE DEP."FechaHoraLiquidacion" END WHERE DEP."IdDeposito" = :Id AND :Entidad = 'TES.Deposito'
